"""Embedded Vox Studio six-tab shell for the FastAPI dashboard.

The module deliberately keeps the first UI slice dependency-free: the browser
receives a deterministic shell and calls the JSON endpoints from ``web_app``.
Business behavior stays in services/providers; this file owns presentation and
small browser-side state helpers only.
"""

from __future__ import annotations

from html import escape

from app.version import APP_VERSION

NAV_ITEMS = (
    ("projects", "▦", "Projects"),
    ("script", "▤", "Script"),
    ("visuals", "▧", "Visuals"),
    ("style", "✦", "Vox Style"),
    ("voice", "◉", "Voice"),
    ("caption", "≡", "Caption"),
    ("render", "▣", "Render"),
)


def render_shell() -> str:
    """Return the complete Vox Studio HTML document."""
    nav = "".join(
        f'<button class="nav-item" data-view="{key}" type="button" onclick="showView(\'{key}\')">'
        f'<span class="nav-icon">{icon}</span><span>{label}</span></button>'
        for key, icon, label in NAV_ITEMS
    )
    return f"""<!doctype html>
<html lang="vi">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Vox Studio v{escape(APP_VERSION)}</title>
<style>
:root {{ --bg:#090b12; --panel:#111522; --panel2:#171b29; --line:#252b3b; --text:#f2f2f7; --muted:#8b91a7; --purple:#7c5cff; --purple2:#9b86ff; --green:#32d583; --orange:#f6a64b; --red:#ff647c; --blue:#5eb1ff; }}
* {{ box-sizing:border-box; }} body {{ margin:0; min-height:100vh; background:#eef0f5; color:var(--text); font-family:Inter,"Segoe UI",system-ui,sans-serif; }}
button,input,textarea,select {{ font:inherit; }} button {{ cursor:pointer; }}
.app {{ min-height:100vh; display:flex; max-width:1600px; margin:0 auto; background:linear-gradient(135deg,#090b12,#0d1020 60%,#11152a); }}
.sidebar {{ width:244px; flex:0 0 244px; border-right:1px solid var(--line); padding:22px 14px 16px; display:flex; flex-direction:column; gap:18px; background:rgba(10,12,20,.9); }}
.brand {{ display:flex; align-items:center; gap:9px; padding:0 10px 8px; font-weight:800; font-size:18px; }} .brand-mark {{ width:30px;height:30px;border-radius:9px;background:linear-gradient(135deg,var(--purple),#b69bff);display:grid;place-items:center;color:white; }}
.pro {{ font-size:10px; color:#c8bcff; border:1px solid #6650d9; border-radius:5px; padding:2px 5px; }}
.primary {{ width:100%; background:var(--purple); color:white; border:0; border-radius:9px; padding:11px 12px; font-weight:700; box-shadow:0 8px 24px rgba(124,92,255,.24); }}
.nav {{ display:flex; flex-direction:column; gap:4px; }} .nav-item {{ display:flex; gap:11px; align-items:center; width:100%; border:1px solid transparent; border-radius:8px; background:transparent; color:#aab0c3; padding:10px 12px; text-align:left; }} .nav-item:hover,.nav-item.active {{ color:white; background:#211b3d; border-color:#5d47c8; }} .nav-icon {{ width:18px; text-align:center; color:var(--purple2); }}
.section-label {{ color:#666d83; font-size:10px; font-weight:800; letter-spacing:.12em; padding:2px 12px; }} .library {{ border-top:1px solid var(--line); padding-top:14px; }}
.user-card {{ margin-top:auto; border:1px solid var(--line); background:var(--panel); border-radius:12px; padding:12px; color:#b8bed0; font-size:11px; }} .user-top {{ display:flex; gap:9px; align-items:center; }} .avatar {{ width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:#634be0;color:white;font-weight:800; }} .storage {{ margin-top:10px; color:var(--muted); }} .storage-bar {{ margin-top:6px;height:5px;background:#252a3a;border-radius:99px;overflow:hidden; }} .storage-bar i {{ display:block;width:25%;height:100%;background:var(--purple); }}
.main {{ min-width:0; flex:1; padding:22px 28px 28px; overflow:auto; }} .topbar {{ display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:16px;margin-bottom:24px; }} .top-actions {{ display:flex;gap:8px; }} .ghost {{ background:transparent;color:#c4c9da;border:1px solid var(--line);border-radius:8px;padding:8px 11px; }} .ghost:hover {{ border-color:var(--purple); color:white; }}
.view {{ display:none; }} .view.active {{ display:block; }} .page-head {{ display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:20px; }} h1 {{ margin:0;font-size:26px;letter-spacing:-.03em; }} h2 {{ margin:0 0 14px;font-size:15px; }} .muted {{ color:var(--muted);font-size:12px; }} .search {{ background:var(--panel);border:1px solid var(--line);border-radius:8px;color:white;padding:10px 12px;min-width:220px; }}
.cards {{ display:grid;grid-template-columns:repeat(5,minmax(120px,1fr));gap:12px;margin-bottom:24px; }} .stat {{ background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:15px; }} .stat .label {{ color:var(--muted);font-size:11px; }} .stat strong {{ display:block;font-size:23px;margin-top:8px; }} .stat small {{ color:#aab0c3;font-size:11px; }}
.panel {{ background:var(--panel);border:1px solid var(--line);border-radius:13px;padding:18px;margin-bottom:18px; }} .panel-head {{ display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:14px; }} .project-grid,.template-grid {{ display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px; }} .project-card,.template-card {{ background:var(--panel2);border:1px solid var(--line);border-radius:11px;padding:12px;min-height:130px; }} .project-card:hover,.template-card:hover {{ border-color:#6e57e8;transform:translateY(-1px); }} .thumb {{ height:92px;border-radius:8px;background:linear-gradient(135deg,#29213d,#161a27 55%,#6a2431);display:grid;place-items:center;color:#d8ccff;font-weight:800;letter-spacing:.08em;font-size:11px; }} .card-title {{ margin-top:10px;font-weight:700;font-size:12px; }} .card-meta {{ color:var(--muted);font-size:10px;margin-top:5px;display:flex;justify-content:space-between;gap:5px; }} .status {{ display:inline-flex;padding:3px 7px;border-radius:99px;font-size:9px;font-weight:800; }} .status.done {{ color:var(--green);background:rgba(50,213,131,.12); }} .status.run {{ color:var(--orange);background:rgba(246,166,75,.12); }} .status.wait {{ color:#b9a9ff;background:rgba(124,92,255,.15); }}
.tip {{ display:flex;justify-content:space-between;align-items:center;gap:16px;background:linear-gradient(100deg,#4a33c4,#7c5cff);border-radius:12px;padding:16px 18px;color:#fff; }} .tip strong {{ display:block;font-size:13px; }} .tip span {{ font-size:11px;color:#e5e0ff; }}
.workspace {{ display:grid;grid-template-columns:230px minmax(0,1fr) 270px;gap:14px; }} .scene-list {{ display:flex;flex-direction:column;gap:7px; }} .scene-row {{ text-align:left;background:#151a29;border:1px solid var(--line);color:#c3c9d9;border-radius:8px;padding:10px; }} .scene-row.active,.scene-row:hover {{ border-color:var(--purple);background:#241d42;color:white; }} .field {{ margin-bottom:13px; }} .field label {{ display:block;color:#aeb4c7;font-size:11px;margin-bottom:6px; }} .field input,.field textarea,.field select {{ width:100%;background:#0b0e17;border:1px solid var(--line);border-radius:8px;color:white;padding:10px; }} .field textarea {{ min-height:180px;resize:vertical; }} .actions {{ display:flex;gap:8px;flex-wrap:wrap;margin-top:12px; }} .btn {{ border:0;border-radius:8px;padding:10px 13px;font-weight:700; }} .btn.primary {{ background:var(--purple);color:#fff; }} .btn.secondary {{ background:#272c3d;color:#e2e5ef; }} .btn.danger {{ background:#682437;color:#ffd9df; }} .btn:disabled {{ opacity:.45;cursor:not-allowed; }} .notice {{ border-radius:8px;padding:10px;margin-top:12px;font-size:11px;background:#1a2030;color:#aeb7cb; }} .notice.warn {{ border:1px solid #694e24;color:#f4c878;background:#241d12; }} .notice.ok {{ border:1px solid #235c43;color:#8bf0b9;background:#10231b; }}
.progress {{ height:8px;background:#252a3a;border-radius:99px;overflow:hidden;margin:12px 0; }} .progress i {{ display:block;height:100%;width:0;background:var(--purple);transition:width .25s; }} .stage-row {{ display:grid;grid-template-columns:repeat(5,1fr);gap:6px; }} .stage {{ border-top:3px solid #30364a;padding-top:7px;color:var(--muted);font-size:10px;text-align:center; }} .stage.done {{ border-color:var(--green);color:var(--green); }} .stage.active {{ border-color:var(--purple);color:white; }} .empty {{ color:var(--muted);font-size:12px;padding:24px;text-align:center;border:1px dashed var(--line);border-radius:10px; }}
:focus-visible {{ outline:3px solid #b4a6ff;outline-offset:2px; }}
@media(max-width:1100px) {{ .sidebar{{width:205px;flex-basis:205px}} .cards{{grid-template-columns:repeat(3,1fr)}} .project-grid,.template-grid{{grid-template-columns:repeat(2,1fr)}} .workspace{{grid-template-columns:190px minmax(0,1fr)}} .workspace > aside:last-child{{grid-column:1/-1}} }}
@media(max-width:760px) {{ .app{{display:block}} .sidebar{{width:100%;border-right:0;border-bottom:1px solid var(--line)}} .nav{{display:grid;grid-template-columns:repeat(4,1fr)}} .nav-item{{font-size:11px;padding:8px}} .user-card,.library{{display:none}} .main{{padding:16px}} .topbar,.page-head{{align-items:stretch;flex-direction:column}} .top-actions{{flex-wrap:wrap}} .cards{{grid-template-columns:repeat(2,1fr)}} .workspace{{display:block}} .workspace > *{{margin-bottom:14px}} }}
</style>
</head>
<body>
<div class="app">
<aside class="sidebar">
  <div class="brand"><span class="brand-mark">▶</span><span>Vox Studio</span><span class="pro">Pro</span></div>
  <button class="primary" type="button" onclick="newProject()">＋ Tạo dự án mới</button>
  <nav class="nav" aria-label="Điều hướng chính">{nav}</nav>
  <div class="library"><div class="section-label">THƯ VIỆN</div><button class="nav-item" type="button" onclick="showNotice('Template catalog sẽ dùng API catalog ở phase tiếp theo.')"><span class="nav-icon">▦</span><span>Template</span></button><button class="nav-item" type="button" onclick="showNotice('Style Presets đã dùng catalog engine.')"><span class="nav-icon">✦</span><span>Style Presets</span></button><button class="nav-item" type="button" onclick="showNotice('Asset Library đọc từ project artifact store.')"><span class="nav-icon">▧</span><span>Asset Library</span></button></div>
  <div class="user-card"><div class="user-top"><span class="avatar">V</span><span><b>Vox User</b><br><span class="muted">Local workspace</span></span><span class="pro">Pro</span></div><div class="storage">Dung lượng: local project store</div><div class="storage-bar"><i></i></div></div>
</aside>
<main class="main">
  <div class="topbar"><div class="muted" id="context-label">Chưa chọn dự án</div><div class="top-actions"><button class="ghost" type="button" onclick="loadProjects()">▣ Mở dự án</button><button class="ghost" type="button" onclick="showNotice('Hướng dẫn: đi từ Script → Visuals → Voice → Caption → Render.')">? Hướng dẫn</button><button class="ghost" type="button" onclick="showView('projects')">⚙ Cài đặt</button></div></div>
  <div id="notice" role="status" aria-live="polite"></div>
  <section id="view-projects" class="view active"><div class="page-head"><div><h1>Dự án của bạn</h1><div class="muted">Tạo, quản lý và tiếp tục các video đang làm.</div></div><div><input class="search" id="project-search" placeholder="⌕ Tìm dự án..." oninput="filterProjects()"></div></div><div class="cards"><div class="stat"><span class="label">Tổng dự án</span><strong id="stat-total">0</strong><small>folder</small></div><div class="stat"><span class="label">Đã hoàn thành</span><strong id="stat-done">0</strong><small class="status done">● ready</small></div><div class="stat"><span class="label">Đang xử lý</span><strong id="stat-run">0</strong><small class="status run">● running</small></div><div class="stat"><span class="label">Chờ render</span><strong id="stat-wait">0</strong><small class="status wait">● waiting</small></div><div class="stat"><span class="label">Tổng thời lượng</span><strong id="stat-duration">—</strong><small>from timeline</small></div></div><div class="panel"><div class="panel-head"><h2>DỰ ÁN GẦN ĐÂY</h2><button class="ghost" type="button" onclick="loadProjects()">Xem tất cả →</button></div><div id="project-grid" class="project-grid"><div class="empty">Đang tải projects...</div></div></div><div class="panel"><div class="panel-head"><h2>TEMPLATE NỔI BẬT</h2><span class="muted">Bắt đầu nhanh bằng preset engine</span></div><div id="template-grid" class="template-grid"></div></div><div class="tip"><div><strong>💡 Mẹo nhanh</strong><span>Bắt đầu bằng script ngắn, kiểm tra storyboard rồi mới gọi voice/image provider.</span></div><button class="btn secondary" type="button" onclick="newProject()">Tạo dự án mới ＋</button></div></section>
  <section id="view-script" class="view"><div class="page-head"><div><h1>Script</h1><div class="muted">AI viết kịch bản và storyboard có kiểm tra schema.</div></div><button class="btn primary" type="button" onclick="planProject()">✦ AI viết kịch bản</button></div><div class="panel"><div class="field"><label for="script-title">Tên dự án</label><input id="script-title" placeholder="Ví dụ: Thạch Trang - Mặt Thật"></div><div class="field"><label for="script-editor">NỘI DUNG KỊCH BẢN</label><textarea id="script-editor" placeholder="Dán script hoặc ý tưởng vào đây..."></textarea></div><div class="actions"><button class="btn secondary" type="button" onclick="saveScript()">Lưu script</button><button class="btn primary" type="button" onclick="planProject()">Tạo storyboard</button></div><div id="script-result" class="notice">Chưa có storyboard cho project này.</div></div><div class="panel"><div class="panel-head"><h2>KỊCH BẢN / CẢNH</h2><span id="scene-count" class="muted">0 cảnh</span></div><div id="script-scenes" class="scene-list"></div></div></section>
  <section id="view-visuals" class="view"><div class="page-head"><div><h1>Visuals</h1><div class="muted">Prompt, scene assets và image generation.</div></div></div><div class="workspace"><aside class="panel"><h2>DANH SÁCH CẢNH</h2><div id="visual-scenes" class="scene-list"></div></aside><div class="panel"><h2 id="prompt-title">PROMPT CHO CẢNH</h2><div class="field"><label for="prompt-editor">Prompt</label><textarea id="prompt-editor" placeholder="Chọn scene để sửa prompt"></textarea></div><div class="field"><label for="visual-ratio">Tỷ lệ</label><select id="visual-ratio"><option>9:16</option><option>16:9</option><option>1:1</option></select></div><div class="actions"><button class="btn secondary" type="button" onclick="savePrompt()">Lưu prompt</button><button class="btn primary" type="button" onclick="generateImage()">✦ Tạo ảnh</button></div><div id="visual-notice" class="notice warn">Chọn scene trước khi generate.</div></div><aside class="panel"><h2>ẢNH ĐÃ CHỌN</h2><div id="selected-image" class="empty">Chưa có ảnh selected.</div><div id="image-results" class="scene-list" style="margin-top:10px"></div></aside></div></section>
  <section id="view-style" class="view"><div class="page-head"><div><h1>Vox Style</h1><div class="muted">Preset style và style anchor của storyboard.</div></div><button class="btn primary" type="button" onclick="saveStyle()">Lưu style</button></div><div class="panel"><div class="field"><label for="style-preset">CHỌN STYLE</label><select id="style-preset"><option value="editorial_collage">Vox Classic</option><option value="johnny_harris_geopolitics">Johnny Harris (Bản đồ & Địa chính trị)</option><option value="magnates_media_billionaires">Magnates Media (Đại án & Tỷ phú)</option><option value="true_crime_dossier">True Crime (Hồ sơ trinh thám)</option><option value="archival_vintage_history">Archival Vintage (Lịch sử & Danh nhân)</option><option value="cyberpunk_tech_breakdown">Cyberpunk Tech (AI & Thung lũng Silicon)</option><option value="tactical_investigation">Tactical Radar (Quân sự & Hàng không)</option><option value="documentary">Vox Documentary</option><option value="minimal_motion">Vox Modern</option></select></div><div class="field"><label for="style-notes">TÙY CHỈNH STYLE / STYLE ANCHOR</label><textarea id="style-notes" placeholder="Palette, texture, typography, continuity rules..."></textarea></div><div id="style-notice" class="notice">Style metadata sẽ được lưu cùng storyboard manifest.</div></div></section>
  <section id="view-voice" class="view"><div class="page-head"><div><h1>Voice</h1><div class="muted">Voice catalog và TTS theo từng scene.</div></div><button class="btn primary" type="button" onclick="generateVoice()">◉ Tạo voice</button></div><div class="panel"><div class="field"><label for="voice-profile">VOICE PROFILE</label><select id="voice-profile"><option value="voice_vi_01">voice_vi_01 — OmniVoice</option></select></div><div id="voice-notice" class="notice warn">Kiểm tra OmniVoice worker trước khi tạo voice.</div><div class="actions"><button class="btn secondary" type="button" onclick="checkProviders()">Kiểm tra provider</button><button class="btn primary" type="button" onclick="generateVoice()">Tạo voice cho project</button></div></div></section>
  <section id="view-caption" class="view"><div class="page-head"><div><h1>Voice & Caption</h1><div class="muted">Tạo SRT từ narration timing và tải artifact thật.</div></div><button class="btn primary" type="button" onclick="generateCaption()">≡ Tạo caption</button></div><div class="panel"><div id="caption-table" class="empty">Chưa có subtitle artifact.</div><div class="actions"><button class="btn secondary" type="button" onclick="generateCaption()">Tạo lại caption</button><button id="download-srt" class="btn primary" type="button" disabled onclick="downloadSrt()">Tải SRT</button></div></div></section>
  <section id="view-render" class="view"><div class="page-head"><div><h1>Render</h1><div class="muted">Xuất video cuối với progress, artifact và trạng thái COMPLETED.</div></div><button class="btn primary" type="button" onclick="renderProject()">▣ Render video</button></div><div class="panel"><div class="workspace"><div><div class="field"><label>Aspect ratio</label><select id="render-ratio"><option>9:16</option><option selected>16:9</option></select></div><div class="field"><label>FPS</label><select id="render-fps"><option selected>30</option><option>60</option></select></div><div class="field"><label>Output</label><input id="render-output" readonly placeholder="final/final.mp4"></div><div class="actions"><button class="btn primary" type="button" onclick="renderProject()">Render final</button><button id="cancel-render" class="btn danger" type="button" disabled onclick="cancelCurrentJob()">Dừng render</button></div></div><div><div id="render-preview" class="empty" style="min-height:180px">Preview sẽ xuất hiện sau khi có final.mp4.</div><div class="progress"><i id="render-progress"></i></div><div class="stage-row"><span class="stage" data-render-stage="prepare">Chuẩn bị</span><span class="stage" data-render-stage="scenes">Render cảnh</span><span class="stage" data-render-stage="audio">Ghép audio</span><span class="stage" data-render-stage="compose">Xuất video</span><span class="stage" data-render-stage="validate">Validate</span></div><div id="render-notice" class="notice">Chưa chạy render.</div></div></div></div></section>
</main></div>
<script>
const API=''; let currentProjectId=null; let currentSceneId=null; let projects=[]; let scenes=[]; let activeJob=null; let pollTimer=null;
const $=id=>document.getElementById(id); const esc=v=>{{const n=document.createElement('span');n.textContent=String(v??'');return n.innerHTML;}};
function showNotice(text,kind=''){{ $('notice').innerHTML=`<div class="notice ${{kind}}">${{esc(text)}}</div>`; }}
function showView(view){{ document.querySelectorAll('.view').forEach(v=>v.classList.remove('active')); $('view-'+view).classList.add('active'); document.querySelectorAll('.nav-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view)); if(view==='projects')loadProjects(); if(view==='script')loadScript(); if(view==='visuals')loadScenes(); if(view==='style')loadStyle(); if(view==='caption')loadCaption(); if(view==='render')loadArtifacts(); }}
function newProject(){{ currentProjectId=null; $('context-label').textContent='Dự án mới'; $('script-title').value=''; $('script-editor').value=''; showView('script'); showNotice('Nhập script rồi bấm Lưu script để tạo project.', 'ok'); }}
async function api(path,opts={{}}){{ const r=await fetch(API+path,{{headers:{{'Content-Type':'application/json'}},...opts}}); let d={{}}; try{{d=await r.json();}}catch{{}} if(!r.ok)throw new Error(d.detail||d.message||`HTTP ${{r.status}}`); return d; }}
async function loadProjects(){{ try{{const d=await api('/api/vox/projects');projects=d.projects||[];renderProjects();}}catch(e){{showNotice('Không tải được projects: '+e.message,'warn')}} }}
function renderProjects(){{const q=($('project-search')?.value||'').toLowerCase();const rows=projects.filter(p=>(p.title+' '+p.project_id).toLowerCase().includes(q));$('stat-total').textContent=projects.length;$('stat-done').textContent=projects.filter(p=>p.status==='COMPLETED').length;$('stat-run').textContent=projects.filter(p=>p.status==='IN_PROGRESS').length;$('stat-wait').textContent=projects.filter(p=>p.status==='IN_PROGRESS'&&!p.has_final).length;$('project-grid').innerHTML=rows.length?rows.map(p=>`<button class="project-card" type="button" onclick="selectProject('${{esc(p.project_id)}}')"><div class="thumb">${{p.has_final?'FINAL VIDEO':'VOX PROJECT'}}</div><div class="card-title">${{esc(p.title||p.project_id)}}</div><div class="card-meta"><span>${{p.scene_count||0}} cảnh</span><span class="status ${{p.has_final?'done':'run'}}">${{p.has_final?'HOÀN THÀNH':'ĐANG LÀM'}}</span></div></button>`).join(''):'<div class="empty">Chưa có project. Bấm Tạo dự án mới.</div>';}}
function filterProjects(){{renderProjects();}} async function selectProject(id){{currentProjectId=id;$('context-label').textContent='Project: '+id;try{{const p=await api('/api/vox/projects/'+encodeURIComponent(id));$('script-title').value=p.title||'';}}catch(e){{}}showView('script');}}
async function saveScript(){{if(!currentProjectId){{const d=await api('/api/vox/projects',{{method:'POST',body:JSON.stringify({{script:$('script-editor').value,title:$('script-title').value,style:$('style-preset').value,aspect_ratio:$('render-ratio').value}})}});currentProjectId=d.project_id;}}else await api('/api/vox/projects/'+encodeURIComponent(currentProjectId)+'/script',{{method:'PUT',body:JSON.stringify({{script:$('script-editor').value,title:$('script-title').value}})}});$('context-label').textContent='Project: '+currentProjectId;showNotice('Đã lưu script vào project '+currentProjectId,'ok');loadProjects();}}
async function loadScript(){{if(!currentProjectId)return;try{{const d=await api('/api/vox/projects/'+encodeURIComponent(currentProjectId)+'/script');$('script-editor').value=d.script||'';const s=await api('/api/vox/projects/'+encodeURIComponent(currentProjectId)+'/scenes');scenes=s.scenes||[];renderScriptScenes();}}catch(e){{showNotice(e.message,'warn')}}}}
function renderScriptScenes(){{$('scene-count').textContent=scenes.length+' cảnh';$('script-scenes').innerHTML=scenes.length?scenes.map(s=>`<button class="scene-row" type="button" onclick="selectScene('${{esc(s.scene_id)}}')">${{String(s.order||'').padStart(2,'0')}} · ${{esc(s.narration_text||s.scene_id)}}<br><span class="muted">${{esc(s.status||'PLANNED')}}</span></button>`).join(''):'<div class="empty">Chưa có storyboard. Bấm Tạo storyboard.</div>';}}
async function planProject(){{if(!currentProjectId)await saveScript();const d=await api('/api/vox/projects/'+encodeURIComponent(currentProjectId)+'/plan',{{method:'POST'}});trackJob(d.job_id,'Storyboard');}}
async function loadScenes(){{if(!currentProjectId)return;const d=await api('/api/vox/projects/'+encodeURIComponent(currentProjectId)+'/scenes');scenes=d.scenes||[];renderVisualScenes();if(!currentSceneId&&scenes[0])selectScene(scenes[0].scene_id);}}
function renderVisualScenes(){{$('visual-scenes').innerHTML=scenes.length?scenes.map(s=>`<button class="scene-row ${{s.scene_id===currentSceneId?'active':''}}" type="button" onclick="selectScene('${{esc(s.scene_id)}}')">${{String(s.order||'').padStart(2,'0')}} ${{esc(s.narration_text||s.scene_id)}}</button>`).join(''):'<div class="empty">Chưa có scenes.</div>';}}
function selectScene(id){{currentSceneId=id;const s=scenes.find(x=>x.scene_id===id)||{{}};$('prompt-title').textContent='PROMPT CHO '+id;$('prompt-editor').value=s.image_prompt||'';$('visual-notice').textContent='Scene '+id+' đã chọn.';renderVisualScenes();}}
async function savePrompt(){{if(!currentProjectId||!currentSceneId)return showNotice('Chọn project và scene trước.','warn');try{{await api(`/api/vox/projects/${{encodeURIComponent(currentProjectId)}}/scenes/${{encodeURIComponent(currentSceneId)}}/prompt`,{{method:'POST',body:JSON.stringify({{prompt:$('prompt-editor').value}})}});showNotice('Đã lưu prompt cho '+currentSceneId,'ok');}}catch(e){{showNotice(e.message,'warn')}}}}
async function generateImage(){{if(!currentProjectId||!currentSceneId)return showNotice('Chọn project và scene trước.','warn');try{{const d=await api(`/api/vox/projects/${{encodeURIComponent(currentProjectId)}}/scenes/${{encodeURIComponent(currentSceneId)}}/images/generate`,{{method:'POST'}});trackJob(d.job_id,'Tạo ảnh');}}catch(e){{showNotice(e.message,'warn')}}}}
async function loadStyle(){{if(!currentProjectId)return;try{{const d=await api('/api/vox/projects/'+encodeURIComponent(currentProjectId)+'/style');$('style-preset').value=d.preset||'editorial_collage';$('style-notes').value=JSON.stringify(d.style||{{}},null,2);}}catch(e){{}}}}
async function saveStyle(){{if(!currentProjectId)return showNotice('Tạo/chọn project trước.','warn');let style={{}};try{{style=JSON.parse($('style-notes').value||'{{}}')}}catch{{return showNotice('Style anchor phải là JSON hợp lệ.','warn')}}await api('/api/vox/projects/'+encodeURIComponent(currentProjectId)+'/style',{{method:'PUT',body:JSON.stringify({{preset:$('style-preset').value,style}})}});showNotice('Đã lưu Vox Style vào manifest.','ok');}}
async function checkProviders(){{try{{const d=await api('/providers/health');const omni=(d.checks||[]).find(x=>x.name==='omnivoice');$('voice-notice').className='notice '+(omni?.status==='ok'?'ok':'warn');$('voice-notice').textContent=omni?.status==='ok'?'OmniVoice worker sẵn sàng.': 'OmniVoice chưa sẵn sàng: khởi động worker trước khi tạo voice.';}}catch(e){{showNotice(e.message,'warn')}}}}
async function generateVoice(){{if(!currentProjectId)return showNotice('Tạo/chọn project trước.','warn');try{{const d=await api(`/api/vox/projects/${{encodeURIComponent(currentProjectId)}}/voice`,{{method:'POST'}});trackJob(d.job_id,'Tạo voice');}}catch(e){{showNotice(e.message,'warn')}}}}
async function generateCaption(){{if(!currentProjectId)return showNotice('Tạo/chọn project trước.','warn');try{{const d=await api(`/api/vox/projects/${{encodeURIComponent(currentProjectId)}}/captions`,{{method:'POST'}});trackJob(d.job_id,'Tạo caption');}}catch(e){{showNotice(e.message,'warn')}}}}
async function loadCaption(){{if(!currentProjectId)return;const d=await api('/api/vox/projects/'+encodeURIComponent(currentProjectId)+'/artifacts');const s=(d.artifacts||[]).find(x=>x.kind==='final'&&x.name.endsWith('.srt'));$('caption-table').textContent=s?'SRT artifact: '+s.name:'Chưa có subtitles.srt';$('download-srt').disabled=!s;}}
function downloadSrt(){{if(currentProjectId)window.open(`/api/vox/media/${{encodeURIComponent(currentProjectId)}}/final/subtitles.srt`,'_blank');}}
async function renderProject(){{if(!currentProjectId)return showNotice('Tạo/chọn project trước.','warn');try{{const d=await api(`/api/vox/projects/${{encodeURIComponent(currentProjectId)}}/render`,{{method:'POST'}});trackJob(d.job_id,'Render video');}}catch(e){{showNotice(e.message,'warn')}}}}
async function loadArtifacts(){{if(!currentProjectId)return;const d=await api('/api/vox/projects/'+encodeURIComponent(currentProjectId)+'/artifacts');const f=(d.artifacts||[]).find(x=>x.kind==='final'&&x.name==='final.mp4');$('render-output').value=f?.name||'final/final.mp4';$('render-preview').innerHTML=f?`<video controls style="max-width:100%;max-height:260px" src="${{f.url}}"></video>`:'Preview sẽ xuất hiện sau khi có final.mp4.';}}
function cancelCurrentJob(){{if(activeJob)fetch('/projects/'+encodeURIComponent(currentProjectId)+'/cancel',{{method:'POST'}});}}
function trackJob(id,label){{activeJob=id;showNotice(label+' đang chạy...');pollTimer=setInterval(async()=>{{try{{const j=await api('/api/job/'+id);if(j.status!=='running'){{clearInterval(pollTimer);activeJob=null;showNotice(j.status==='completed'?label+' hoàn tất.':label+' thất bại: '+j.detail,j.status==='completed'?'ok':'warn');loadScript();loadProjects();}}}}catch{{}}}},1200);}}
$('template-grid').innerHTML=[['Vox Documentary','9:16'],['Vox History','9:16'],['Vox Explainer','9:16'],['Vox Tech','9:16']].map(x=>`<button class="template-card" type="button" onclick="newProject();$('style-preset').value='${{x[0].toLowerCase().replace(' ','_')}}'"><div class="thumb">${{x[0].toUpperCase()}}</div><div class="card-title">${{x[0]}}</div><div class="card-meta"><span>${{x[1]}}</span><span>01:00</span></div></button>`).join('');
loadProjects();showView('projects');
</script>
</body></html>"""
